export function evaluate({ inputs, time }) {
  const u = inputs.launchSpeed, g = inputs.gravity, m = inputs.mass;
  const T = 2 * u / g, ta = u / g;
  const t = Math.max(0, Math.min(time, T));
  const y = u * t - g * t * t / 2;
  const v = u - g * t;
  const H = u * u / (2 * g);
  const F = m * g;
  let st = 'Rising';
  if (t <= 0) st = 'Ready to toss';
  else if (t >= T - 1e-9) st = 'Back at launch height';
  else if (Math.abs(t - ta) < 0.005) st = 'At the top';
  else if (t > ta) st = 'Falling';
  const objs = [];
  objs.push(...sdk.panel({ id: 'lane.motion', x: 10, y: 30, w: 300, h: 380, title: 'The motion', state: st }));
  objs.push(...sdk.panel({ id: 'lane.graph', x: 330, y: 30, w: 300, h: 380, title: 'Velocity over time', state: '' }));
  const y0 = 380, ppm = 140;
  objs.push(sdk.axis('axis.h', { x: 70, y: y0, length: 2.2 * ppm, orientation: 'y', min: 0, max: 2.2, ticks: [0, 0.5, 1, 1.5, 2], label: 'Height', unit: 'm' }));
  const by = y0 - y * ppm;
  objs.push(sdk.circle('ball.toss', 130, by, 26));
  objs.push(...sdk.vector('vec.v', { x: 130, y: by - 20 * 0 }, { value: v, direction: 'up' }, { scale: 14, label: 'v', role: 'observed' }));
  objs.push(...sdk.vector('vec.a', { x: 160, y: by }, { value: -g, direction: 'up' }, { scale: 6, label: 'a', role: 'warning' }));
  objs.push(sdk.callout(185, 120, ['v = ' + sdk.format(v, 2) + ' m/s', 'a = ' + sdk.format(-g, 1) + ' m/s²', 'Fg = ' + sdk.format(F, 1) + ' N'], { id: 'callout.toss' }));
  const pts = sdk.sample(s => u - g * s * 1.8 / 1.8, 0, T, 20).map(p => ({ x: p[0] * 0 + p[0] / 1 * 0 + (p[0]) * 0 + p[0] * 0, y: 0 }));
  const n = 20, ser = [];
  for (let i = 0; i <= n; i++) { const s = Math.min(t, T) * i / n; ser.push({ x: s, y: u - g * s }); }
  const full = [];
  for (let i = 0; i <= n; i++) { const s = T * i / n; full.push({ x: s, y: u - g * s }); }
  objs.push(sdk.plot('plot.vt', { x: 340, y: 60, w: 285, h: 300, axes: { x: { label: 'Time', min: 0, max: 1.8, unit: 's' }, y: { label: 'Velocity', min: -5.5, max: 5.5, unit: 'm/s' } }, series: [{ label: 'v = u - g t', kind: 'line', points: full }, { label: 'so far', kind: 'line', points: ser.length > 1 && t > 0 ? ser : [{ x: 0, y: u }, { x: 0.001, y: u - g * 0.001 }] }] }));
  objs.push(sdk.text('plot.vt.note', 480, 395, 'slope a = -g = ' + sdk.format(-g, 1) + ' m/s²', { align: 'middle' }));
  return { frame: { width: 640, height: 420, objects: objs, readouts: [{ id: 'velocity', value: v }, { id: 'acceleration', value: -g }, { id: 'force', value: F }, { id: 'motionState', value: st }] }, quantities: { launchSpeed: u, gravity: g, mass: m, apexTime: ta, apexHeight: H, height: y, velocity: v, acceleration: -g, force: F } };
}
